import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, HostListener, Input, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { COUNTRIES } from '../../shared/data/countries';
import { TranslateModule } from '@ngx-translate/core';
import { TranslationService } from '../../core/services/translation.service';
@Component({
  selector: 'app-phone-input',
  imports: [CommonModule, ReactiveFormsModule, TranslateModule],
  templateUrl: './phone-input.component.html',
  styleUrl: './phone-input.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class PhoneInputComponent {
  @Input({ required: true }) form!: FormGroup;
  countries = COUNTRIES;
  isOpen = false;
  isFocused = false;
  @Input() phonePath: string = 'phone';
  @Input() countryPath: string = 'countryCode';
  @Output() phoneChange = new EventEmitter<any>();
  constructor(private cdr: ChangeDetectorRef,
    public translationService: TranslationService,
  ) { }

  countryPhoneRules: Record<string, { length: number; regex?: RegExp }> = {
    '+91': { length: 10, regex: /^[6-9]\d{9}$/ },
    '+1': { length: 10, regex: /^[2-9]\d{9}$/ },
    '+44': { length: 10, regex: /^[1-9]\d{9}$/ },
    '+971': { length: 9, regex: /^[5]\d{8}$/ },
    '+61': { length: 9, regex: /^[4-9]\d{8}$/ },
    '+966': { length: 9, regex: /^[5]\d{8}$/ },
    '+974': { length: 8, regex: /^[3-8]\d{7}$/ },
    '+965': { length: 8, regex: /^[5-9]\d{7}$/ },
    '+968': { length: 8, regex: /^[7-9]\d{7}$/ },
    '+973': { length: 8, regex: /^[3-7]\d{7}$/ },
    '+20': { length: 10, regex: /^[1-9]\d{9}$/ },
    '+86': { length: 11, regex: /^[1-9]\d{10}$/ },
  };

  get phoneControl() {
    return this.form.get(this.phonePath) as FormControl;
  }

  onInputChange(value: any) {
    this.phoneChange.emit(value);
    this.validatePhone();
  }

  get parentGroup(): FormGroup {
    const groupName = this.phonePath.split('.')[0];
    return this.form.get(groupName) as FormGroup;
  }

  // get phoneErrorMessage(): string {
  //   if (!this.phoneControl?.invalid || !this.phoneControl?.touched) {
  //     return '';
  //   }

  //   if (this.phoneControl.hasError('required')) {
  //     return 'Phone number is required.';
  //   }

  //   if (this.phoneControl.hasError('invalidDigitCount')) {
  //     const { expected } = this.phoneControl.getError('invalidDigitCount');
  //     return `Phone number must be exactly ${expected} digits for the selected country.`;
  //   }

  //   if (this.phoneControl.hasError('invalidStartDigit')) {
  //     return 'Phone number must start with the correct digits for the selected country.';
  //   }

  //   if (this.phoneControl.hasError('pattern')) {
  //     return 'Please enter a valid phone number.';
  //   }

  //   return 'Phone number is invalid.';
  // }
  get phoneErrorMessage(): string {
    if (!this.phoneControl?.invalid || !this.phoneControl?.touched) {
      return '';
    }

    const isArabic = this.translationService.currentLang() === 'ar';

    if (this.phoneControl.hasError('required')) {
      return isArabic
        ? 'رقم الهاتف مطلوب.'
        : 'Phone number is required.';
    }

    if (this.phoneControl.hasError('invalidDigitCount')) {
      const { expected } = this.phoneControl.getError('invalidDigitCount');

      return isArabic
        ? `يجب أن يتكون رقم الهاتف من ${expected} أرقام بالضبط.`
        : `Phone number must be exactly ${expected} digits for the selected country.`;
    }

    if (this.phoneControl.hasError('invalidStartDigit')) {
      return isArabic
        ? 'يجب أن يبدأ رقم الهاتف بالأرقام الصحيحة الخاصة بالدولة المحددة.'
        : 'Phone number must start with the correct digits for the selected country.';
    }

    if (this.phoneControl.hasError('pattern')) {
      return isArabic
        ? 'يرجى إدخال رقم هاتف صحيح.'
        : 'Please enter a valid phone number.';
    }

    return isArabic
      ? 'رقم الهاتف غير صالح.'
      : 'Phone number is invalid.';
  }
  get selectedCountry() {
    const code = this.form?.get(this.countryPath)?.value;
    return this.countries.find(c => c.dialCode === code) || this.countries[0];
  }

  getExpectedPhoneLength(): number {
    return this.countryPhoneRules[this.selectedCountry.dialCode]?.length ?? 10;
  }

  validatePhone(): void {
    const control = this.phoneControl;
    if (!control) {
      return;
    }

    const value = control.value ?? '';
    const digits = String(value).replace(/\D/g, '');
    const rule = this.countryPhoneRules[this.selectedCountry.dialCode];
    const expected = rule?.length ?? 10;
    const errors = control.errors ? { ...control.errors } : {};

    if (!value) {
      delete errors['invalidDigitCount'];
      delete errors['invalidStartDigit'];
      if (Object.keys(errors).length === 0) {
        control.setErrors(null);
      } else {
        control.setErrors(errors);
      }
      return;
    }

    if (digits.length !== expected) {
      errors['invalidDigitCount'] = { expected, actual: digits.length };
      delete errors['invalidStartDigit'];
      control.setErrors(errors);
      return;
    }

    if (rule?.regex && !rule.regex.test(digits)) {
      delete errors['invalidDigitCount'];
      errors['invalidStartDigit'] = { expected, actual: digits.length };
      control.setErrors(errors);
      return;
    }

    delete errors['invalidDigitCount'];
    delete errors['invalidStartDigit'];
    if (Object.keys(errors).length === 0) {
      control.setErrors(null);
    } else {
      control.setErrors(errors);
    }
  }

  getFlag(code: string): string {
    return `https://flagcdn.com/w40/${code}.png`;
  }


  toggleDropdown() {
    this.isOpen = !this.isOpen;
  }

  selectCountry(country: any) {
    this.form.get(this.countryPath)?.setValue(country.dialCode);
    this.isOpen = false;
    this.validatePhone();
    this.cdr.markForCheck();
  }

  // close on outside click
  @HostListener('document:click', ['$event'])
  onClickOutside(event: Event) {
    const target = event.target as HTMLElement;
    if (!target.closest('.custom-dropdown')) {
      this.isOpen = false;
    }
  }

}
